def validate_record(record):
    def result(status, code, message):
        return {"status": status, "code": code, "message": message}
    edad = record.get("edad")
    if edad is None:
        edad_r = result("review", "MISSING", "Campo 'edad' ausente.")
    elif not isinstance(edad, int):
        edad_r = result("reject", "BAD_TYPE", "Campo 'edad' debe ser int.")
    elif edad < 0 or edad > 120:
        edad_r = result("reject", "OUT_OF_RANGE", "Campo 'edad' fuera de 0–120.")
    elif edad < 18:
        edad_r = result("review", "NEEDS_REVIEW", "Campo 'edad' requiere revisión.")
    else:
        edad_r = result("accept", "OK", "edad OK")
    region = record.get("region")
    if region is None:
        region_r = result("review", "MISSING", "Campo 'region' ausente.")
    elif region not in {"Lima", "Arequipa", "Cusco", "Piura"}:
        region_r = result("review", "NOT_IN_ALLOWLIST", "Campo 'region' fuera del catálogo.")
    else:
        region_r = result("accept", "OK", "region OK")
    monto = record.get("monto_ingreso")
    if monto is None:
        monto_r = result("review", "MISSING", "Campo 'monto_ingreso' ausente.")
    elif not isinstance(monto, int):
        monto_r = result("reject", "BAD_TYPE", "Campo 'monto_ingreso' debe ser int.")
    elif monto < 0:
        monto_r = result("reject", "OUT_OF_RANGE", "Campo 'monto_ingreso' no puede ser negativo.")
    elif monto > 50000:
        monto_r = result("review", "NEEDS_REVIEW", "Campo 'monto_ingreso' requiere revisión.")
    else:
        monto_r = result("accept", "OK", "monto OK")
    fields = {"edad": edad_r, "region": region_r, "monto_ingreso": monto_r}
    statuses = [x["status"] for x in fields.values()]
    status = "reject" if "reject" in statuses else "review" if "review" in statuses else "accept"
    return {"status": status, "fields": fields}

def process_batch(records):
    summary = {"n_total":0,"n_accept":0,"n_reject":0,"n_review":0,"tasa_reject":None,"results":[]}
    for record in records:
        checked = validate_record(record)
        status = checked["status"]
        summary["n_total"] += 1
        summary["n_" + status] += 1
        summary["results"].append({"raw": record.copy(), "status": status, "fields": checked["fields"]})
    if summary["n_total"] > 0:
        summary["tasa_reject"] = summary["n_reject"] / summary["n_total"]
    return summary

def format_report(s):
    return f"total {s['n_total']} | accept {s['n_accept']} | reject {s['n_reject']} | review {s['n_review']} | tasa_reject {s['tasa_reject']}"
